        "@type": "Question",
        "name": "How is BMI calculated?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "BMI is calculated by dividing your weight in kilograms by the square of your height in meters (kg/m²). In imperial units: BMI = (weight in lbs × 703) ÷ (height in inches)²."
        }
