        }
      },
      {
        "@type": "Question",
        "name": "Can I use a BMI calculator during pregnancy?",
        "acceptedAnswer": {
          "@type": "Answer",
          "text": "BMI calculators are not designed for use during pregnancy. Pre-pregnancy BMI is used by healthcare providers to set appropriate weight gain targets. Always consult your OB-GYN for pregnancy weight guidance."
